package com.cyl.tabbar.demo

import android.annotation.SuppressLint
import android.content.Context
import java.lang.ref.WeakReference
import java.security.MessageDigest

/**
 * [EN] The texts of the Android example layer, the counterpart of iOS `CYLDemoLocalizedString()` (AGENTS.md, "Localization
 *      file structure"; docs/Configuration-Localization.md, Android example strings). Code passes the English text; the
 *      translation comes from demokit's `res/values-…/cyl_demo_strings.xml`, generated by `scripts/android-demo-strings.py`
 *      from the iOS example bundle `Example-Shared/CYLDemo.bundle` (and the core bundle for the texts both share), 33
 *      languages. The resource name is `cyl_demo_` + the first 10 hex digits of the text's SHA-256, so the generator and this
 *      helper agree without a generated Kotlin table. A text without a translation is shown as given. `%@` / `%1$@` in a
 *      text are filled with `arguments`, as on iOS.
 * [CN] Android 示例层的文字，对应 iOS 的 `CYLDemoLocalizedString()`（AGENTS.md「Localization file structure」；
 *      docs/Configuration-Localization.md「Android 示例字符串」）。代码传入英文原文；译文来自 demokit 的 `res/values-…/cyl_demo_strings.xml`，
 *      由 `scripts/android-demo-strings.py` 从 iOS 示例 bundle `Example-Shared/CYLDemo.bundle`（两端共用的文字取自核心 bundle）生成，共 33 种语言。
 *      资源名为 `cyl_demo_` 加上文字 SHA-256 的前 10 位十六进制，生成脚本与本工具无需生成的 Kotlin 表即可对应。没有译文的文字原样显示。文字中的
 *      `%@` / `%1$@` 由 `arguments` 填入，与 iOS 相同。
 */
object DemoText {
    private var contextReference: WeakReference<Context>? = null
    private val ids = HashMap<String, Int>()

    /**
     * [EN] The context whose locale the texts follow (the current activity; DemoListFragment and the activities set it).
     * [CN] 文字跟随其语言的 context（当前 Activity；由 DemoListFragment 与各 Activity 设置）。
     */
    fun attach(context: Context) {
        contextReference = WeakReference(context)
    }

    /** [EN] The resource name of an English text. [CN] 英文原文对应的资源名。 */
    fun resourceName(english: String): String {
        val digest = MessageDigest.getInstance("SHA-256").digest(english.toByteArray(Charsets.UTF_8))
        return "cyl_demo_" + digest.joinToString("") { "%02x".format(it) }.substring(0, 10)
    }

    /** [EN] The text in the current language, `arguments` filled in. [CN] 当前语言的文字，填入 `arguments`。 */
    @SuppressLint("DiscouragedApi")
    fun string(english: String, vararg arguments: Any?, context: Context? = contextReference?.get()): String {
        var text = english
        if (context != null) {
            val id = synchronized(ids) { ids.getOrPut(english) { context.resources.getIdentifier(resourceName(english), "string", context.packageName) } }
            if (id != 0) text = context.getString(id)
        }
        return fill(text, arguments)
    }

    /** [EN] `%@` in order, or `%1$@`, `%2$@`... by position, as iOS format strings. [CN] 按顺序填入 `%@`，或按位置填入 `%1$@`、`%2$@`……，与 iOS 格式字符串相同。 */
    fun fill(text: String, arguments: Array<out Any?>): String {
        if (arguments.isEmpty()) return text
        var next = 0
        return Regex("""%(\d+\$)?@""").replace(text) { match ->
            val position = match.groupValues[1].removeSuffix("$").toIntOrNull()
            val index = if (position != null) position - 1 else next++
            arguments.getOrNull(index)?.toString() ?: ""
        }
    }
}

/** [EN] Shorthand of `DemoText.string`. [CN] `DemoText.string` 的简写。 */
fun cylDemoText(english: String, vararg arguments: Any?): String = DemoText.string(english, *arguments)

/**
 * [EN] English keys kept as they are (e.g. tab titles that are also identifiers), listed so that
 *      `scripts/android-demo-strings.py` writes their translations; show them with `cylDemoText(key)`.
 * [CN] 原样保留的英文键（例如同时作为标识的 Tab 标题），列在这里以便 `scripts/android-demo-strings.py` 生成其译文；显示时使用 `cylDemoText(key)`。
 */
fun cylDemoTextKeys(vararg english: String): List<String> = english.toList()

/**
 * [EN] One English key kept as it is (e.g. a title that is also part of a lookup key), listed so that
 *      `scripts/android-demo-strings.py` writes its translations; show it with `cylDemoText(key)`.
 * [CN] 原样保留的一个英文键（例如同时用作查找键一部分的标题），列在这里以便 `scripts/android-demo-strings.py` 生成其译文；显示时使用 `cylDemoText(key)`。
 */
fun cylDemoTextKey(english: String): String = english
